// Génère une base de comptes fictifs, différente à chaque exécution
const NB_COMPTES = 50;
const EMAIL_TEST = 'ton.email@exemple.com'; // tous les mails partent ici
const PRENOMS = ['Lucas','Emma','Hugo','Léa','Louis','Chloé','Nathan','Inès','Yanis','Sarah',
                 'Karim','Julie','Thomas','Camille','Mehdi','Manon','Enzo','Jade','Adam','Lina'];

const now = DateTime.now().setZone('Europe/Paris');
const rand = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

const comptes = [];
for (let i = 0; i < NB_COMPTES; i++) {
  // Dernière activité hippique : entre 0 et 180 jours dans le passé
  // Les 2 premiers comptes garantissent au moins 1 actif et 1 inactif
  const nbJours = i === 0 ? rand(0, 59) : i === 1 ? rand(92, 180) : rand(0, 180);
  const derniere = now.minus({ days: nbJours, hours: rand(0, 23), minutes: rand(0, 59) });
  const jours = Math.floor(now.diff(derniere, 'days').days);

  let segment = 'hors_cible';          // 61 à 90 jours
  if (jours <= 60) segment = 'actif';   // 0 à 60 jours
  else if (jours > 90) segment = 'inactif';

  comptes.push({ json: {
    id_compte: `CPT${String(rand(100000, 999999))}`,
    prenom: PRENOMS[rand(0, PRENOMS.length - 1)],
    email: EMAIL_TEST,
    dt_hr_reference_hippique: derniere.toFormat('yyyy-MM-dd HH:mm:ss'),
    jours_depuis_activite: jours,
    segment
  }});
}
return comptes;

// Calcule le samedi et le dimanche du week-end précédent (heure de Paris)
// Pour forcer d'autres dates : FORCE = ['26092026', '27092026']
const FORCE = null;

const today = DateTime.now().setZone('Europe/Paris').startOf('day');
const sunday = today.minus({ days: today.weekday }); // weekday : lundi=1 ... dimanche=7
const saturday = sunday.minus({ days: 1 });

const days = FORCE
  ? FORCE.map(d => DateTime.fromFormat(d, 'ddMMyyyy', { zone: 'Europe/Paris' }))
  : [saturday, sunday];

return days.map(d => {
  const label = d.setLocale('fr').toFormat('cccc d LLLL');
  return { json: {
    date: d.toFormat('ddMMyyyy'),
    date_iso: d.toISODate(),
    jour: label.charAt(0).toUpperCase() + label.slice(1)
  }};
});

// Chaque réponse HTTP est rattachée à sa date d'origine
const courses = [];

$input.all().forEach((item, i) => {
  const { date, jour } = $('Dates du week-end').itemMatching(i).json;
  const prog = item.json.programme ?? {};

  for (const r of prog.reunions ?? []) {
    for (const c of r.courses ?? []) {
      courses.push({ json: {
        date,
        jour,
        pays: r.pays?.code ?? '',
        hippodrome: r.hippodrome?.libelleCourt ?? '',
        reunion: `R${r.numOfficiel}`,
        course: `C${c.numOrdre}`,
        libelle: c.libelle,
        heure: c.heureDepart
          ? new Date(c.heureDepart).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' })
          : '',
        discipline: c.discipline,
        allocation: c.montantPrix ?? 0,
        partants: c.nombreDeclaresPartants ?? 0,
        gagnant: c.ordreArrivee?.[0]?.length ? `n°${c.ordreArrivee[0].join(' / n°')}` : 'arrivée non dispo',
        arrivee: (c.ordreArrivee ?? []).slice(0, 5).map(x => x.join('=')).join(' - ')
      }});
    }
  }
});

return courses;

// Top 5 avec fallback : 30 000 € -> 15 000 € -> sans seuil
const all = $input.all()
  .map(i => i.json)
  .filter(c => c.course) // ignore l'item vide si le Filter n'a rien gardé
  .sort((a, b) => b.allocation - a.allocation);

if (all.length === 0) {
  throw new Error("Aucune course française récupérée : pas d'envoi.");
}

let seuil = 30000;
let selection = all.filter(c => c.allocation >= seuil);
if (selection.length < 5) { seuil = 15000; selection = all.filter(c => c.allocation >= seuil); }
if (selection.length < 5) { seuil = 0; selection = all; }

return [{ json: {
  courses: selection.slice(0, 5),
  seuil_applique: seuil,
  nb_courses_fr: all.length
}}];

// Construit un mail par compte ciblé (objet + intro selon le segment)
// Démo : un seul mail par segment pour ne pas inonder la boîte de test
const DEMO_UN_PAR_SEGMENT = true;

let comptes = $input.all().map(i => i.json);
if (DEMO_UN_PAR_SEGMENT) {
  const vus = new Set();
  comptes = comptes.filter(c => !vus.has(c.segment) && vus.add(c.segment));
}

const td = 'padding:8px;border-bottom:1px solid #e5e7eb';

return comptes.map(c => {
  const lignes = c.courses.map(k => `
    <tr>
      <td style="${td}">${k.jour}<br><small>${k.heure}</small></td>
      <td style="${td}"><b>${k.libelle}</b><br><small>${k.hippodrome} · ${k.reunion}${k.course} · ${k.discipline}</small></td>
      <td style="${td};text-align:right">${Number(k.allocation).toLocaleString('fr-FR')} €</td>
      <td style="${td};text-align:center"><b>${k.gagnant}</b><br><small>${k.arrivee}</small></td>
    </tr>`).join('');

  const actif = c.segment === 'actif';
  const P = actif ? {
    sujet: `🏇 ${c.prenom}, les 5 courses phares du week-end`,
    bandeau: 'Les 5 courses phares du week-end',
    couleur: '#00543b',
    intro: `Salut ${c.prenom}, tu as suivi les courses dernièrement : voici le récap des plus grosses épreuves du week-end et leurs arrivées.`,
    cta: 'Voir le programme de la semaine',
    ps: 'Un nouveau week-end de belles courses arrive, on te tient au courant lundi prochain.'
  } : {
    sujet: `${c.prenom}, voici ce que tu as raté ce week-end 🏇`,
    bandeau: 'Ce que tu as raté ce week-end',
    couleur: '#b45309',
    intro: `Salut ${c.prenom}, ça fait plus de 3 mois qu'on ne t'a pas vu sur les courses ! Voici les 5 plus belles épreuves du week-end, de quoi te donner envie de revenir.`,
    cta: 'Revenir sur les courses',
    ps: "Envie de t'y remettre ? Le programme de la semaine est déjà en ligne."
  };

  const html = `
<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto">
  <div style="background:${P.couleur};color:#fff;padding:20px;border-radius:10px 10px 0 0">
    <h2 style="margin:0">🏇 ${P.bandeau}</h2>
  </div>
  <p>${P.intro}</p>
  <table style="width:100%;border-collapse:collapse;font-size:14px">
    <tr style="background:#f3f4f6">
      <th style="padding:8px;text-align:left">Jour</th>
      <th style="padding:8px;text-align:left">Course</th>
      <th style="padding:8px;text-align:right">Allocation</th>
      <th style="padding:8px">Gagnant</th>
    </tr>${lignes}
  </table>
  <p style="text-align:center;margin:28px 0">
    <a href="#" style="background:${P.couleur};color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;font-weight:bold">${P.cta}</a>
  </p>
  <p style="font-size:14px">${P.ps}</p>
  <p style="color:#6b7280;font-size:12px;margin-top:24px">
    Jouer comporte des risques : endettement, isolement, dépendance. Pour être aidé, appelez le 09 74 75 13 13 (appel non surtaxé).<br>
    <a href="#" style="color:#6b7280">Se désinscrire</a> · Compte ${c.id_compte} · segment ${c.segment} (démo fictive)
  </p>
</div>`;
  const sujet = P.sujet;

  return { json: { id_compte: c.id_compte, segment: c.segment, email: c.email, sujet, html } };
});
